+  // Check Gnss BestPose.
+  auto *best_pose_adapter = AdapterManager::GetGnssBestPose();
+  best_pose_adapter->Observe();
+  if (best_pose_adapter->Empty()) {
+    status->set_status(HardwareStatus::ERR);
+    status->set_msg("No Gnss BestPose message.");
