+  template <class T>
+  static bool GetNumberFromJson(const nlohmann::json &json,
+                                const std::string &key, T *value) {
+    const auto iter = json.find(key);
+    if (iter == json.end()) {
+      AERROR << "The json has no such key: " << key;
+      return false;
+    }
+    if (!iter->is_number()) {
