+
+
+#ifndef ADU_PERCEPTION_OBSTACLE_CAMERA_INTERFACE_BASE_CAMERA_TRACKER_H
+#define ADU_PERCEPTION_OBSTACLE_CAMERA_INTERFACE_BASE_CAMERA_TRACKER_H
+
+// SAMPLE CODE:
+//
+// class MyCameraTracker : public BaseCameraTracker {
+// public:
+//     MyCameraTracker() : BaseCameraTracker() {}
+//     virtual ~MyCameraTracker() {}
+//
+//     virtual bool init() override {
+//         // Do something.
+//         return true;
+//     }
+//
+//     virtual bool track(const cv::Mat& frame,
+//              const std::vector<VisualObjectPtr>& objects,
+//              double timestamp,
+//              const CameraTrackerOptions& options,
+//              std::vector<VisualObjectPtr>* tracked_objects) override {
+//          // Do something.
+//          return true;
+//      }
+//
+//      virtual std::string name() const override {
+//          return "MyCameraTracker";
