+void DisjointSet::Unite(int x, int y) {
+  if (x == y) {
+    return;
+  }
+
+  int x_root = Find(x);
+  int y_root = Find(y);
+  if (x_root == y_root) {
+    return;
+  } else if (x_root < y_root) {
+    disjoint_array_[y_root] = x_root;
+  } else {
+    disjoint_array_[x_root] = y_root;
+  }
+
+  --subset_num_;
 }
 
