+/** ConnectedComponent **/
+void ConnectedComponent::AddPixel(int x, int y) {
+  if (pixel_count_ == 0) {
+    // new bounding box
+    bbox_.x_min = x;  // x_min
+    bbox_.y_min = y;  // y_min
+    bbox_.x_max = x;  // x_max
+    bbox_.y_max = y;  // y_max
+  } else {
+    // extend bounding box if necessary
+    if (x < bbox_.x_min) {
+      bbox_.x_min = x;
+    }
+    if (x > bbox_.x_max) {
+      bbox_.x_max = x;
+    }
+    if (y < bbox_.y_min) {
+      bbox_.y_min = y;
+    }
+    if (y > bbox_.y_max) {
+      bbox_.y_max = y;
+    }
+  }
+
+  pixels_->push_back(cv::Point(x, y));
+  pixel_count_++;
 }
 
