-    }
-
-    XLOG(INFO) << "uv_p: " << uv_point(0) << ", " << uv_point(1) << ", " << uv_point(2);
-    XLOG(INFO) << "xy_p: " << xy_p(0) << ", " << xy_p(1) << ", " << xy_p(2);
-#endif
-
-    T scale = xy_p(2);
-    if (std::abs(scale) < 1e-6) {
-        XLOG(INFO) << "Cannot solve point: scale factor is too small (" << scale << "), "
-                   << " u=" << u << " v=" << v << ".";
-        return false;
-    }
-
-    (*xy_point) << xy_p(0) / scale, xy_p(1) / scale;
-#if _DEBUG
