-    vertices_->push_back(Vertex(end_pos, y));
-    int end_vertex_id = static_cast<int>(vertices_->size()) - 1;
-
-    int width = end_pos - start_pos + 1;
-    vector<int> lens = GetSplitRanges(width, len_split);
