-void ConnectedComponent::Process(ScalarType split_siz, int split_len) {
-  FindBboxPixels();
-  FindVertices();
-  FindEdges();
-  if (DetermineSplit(split_siz) !=
-      ConnectedComponent::BoundingBoxSplitType::NONE) {
-    FindContourForSplit();
-    SplitContour(split_len);
-  }
-}
