-        cv::mulSpectrums(xf[i], yf[i], xyf, 0, true);
-        cv::idft(xyf, xy_temp, cv::DFT_SCALE | cv::DFT_REAL_OUTPUT);
-        xy += xy_temp;
-    }
-
-    cv::Mat k;
