+bool load_text_proto_message_file(const std::string& path,
+                                  google::protobuf::Message* msg) {
+  if (msg == nullptr) {
+    AERROR << "msg is a null pointer.";
+    return false;
+  }
+
+  int fd = open(path.c_str(), O_RDONLY);
+  if (fd < 0) {
+    AERROR << "path[" << path << "]";
+    return false;
+  }
+
+  google::protobuf::io::FileInputStream file_in(fd);
