-void AsyncTrack::PerformMotionFusion(PbfSensorObjectPtr obj) {
-  if (motion_fusion_ == nullptr) {
-    AERROR << "Skip motion fusion becuase motion_fusion_ is nullptr.";
-    return;
-  }
-
-  const SensorType &sensor_type = obj->sensor_type;
