+template <typename T>
+void QuaternionToRotationMatrix(const T* quat, T* R) {
+  T x2 = quat[0] * quat[0];
+  T xy = quat[0] * quat[1];
+  T rx = quat[3] * quat[0];
+  T y2 = quat[1] * quat[1];
+  T yz = quat[1] * quat[2];
+  T ry = quat[3] * quat[1];
+  T z2 = quat[2] * quat[2];
+  T zx = quat[2] * quat[0];
+  T rz = quat[3] * quat[2];
+  T r2 = quat[3] * quat[3];
+  R[0] = r2 + x2 - y2 - z2;  // fill diagonal terms
+  R[4] = r2 - x2 + y2 - z2;
+  R[8] = r2 - x2 - y2 + z2;
+  R[3] = 2 * (xy + rz);  // fill off diagonal terms
+  R[6] = 2 * (zx - ry);
+  R[7] = 2 * (yz + rx);
+  R[1] = 2 * (xy - rz);
+  R[2] = 2 * (zx + ry);
+  R[5] = 2 * (yz - rx);
+}
+
