-  while (score_index_vec.size() != 0) {
-    const int idx = score_index_vec.front().second;
-    bool keep = true;
-    for (int k = 0; k < static_cast<int>(indices->size()); ++k) {
-      if (keep) {
-        const int kept_idx = (*indices)[k];
