+    derivative += 5.0 * coef_[5] * 4.0 * s3 * r +
+                  4.0 * coef_[4] * 3.0 * s2 * r +
+                  3.0 * coef_[3] * 2.0 * s * r +
+                  2.0 * coef_[2] * r;
+  }
+  return derivative;
